import json
OUT = 'out/verify/p15'
HEAD = "const L = window.squaringLab, $ = id => document.getElementById(id); const type = (id, v) => { const e = $(id); e.value = v; e.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); }; const key = (id, k, o) => $(id).dispatchEvent(new KeyboardEvent('keydown', Object.assign({ key: k, bubbles: true, cancelable: true }, o || {}))); const pick = (id, text) => { const e = $(id), o = [...e.options].find(x => x.text.startsWith(text)); if (!o) throw new Error('no option ' + text); e.value = o.value; e.dispatchEvent(new Event('change', { bubbles: true })); }; const st = () => ({ n: L.S.n, eq: L.S.eq, z0: L.S.z0, dist: L.cam.dist, target: L.cam.target, yaw: L.cam.yaw, pitch: L.cam.pitch, bound: L.S.view.bound, cutOn: L.S.cutOn, cut: L.S.cut, v2: L.S.v2, status: $('status').textContent, note: $('eqNote').hidden ? '' : $('eqNote').textContent }); "
a = []
a.append({"js": HEAD + "L.R.warmOn = false; const r = $('pow'), d = r.closest('.dial'); const out = { min: r.min, max: r.max, step: r.step, play: !!$('powPlay'), toggle: $('powStep') ? $('powStep').textContent + '|' + ($('powStep').getAttribute('aria-label') || '') + '|' + ($('powStep').title || '') : null, buttons: [...d.querySelectorAll('button')].map(b => b.id + ':' + b.textContent + ':' + (b.getAttribute('aria-label') || '')), dialText: d.innerText, eqOptions: [...$('eqPreset').options].map(o => o.text) }; "
  "type('powNum', '-20'); out.t_m20 = [L.S.n, r.value, $('powNum').value]; type('powNum', '30'); out.t_30 = [L.S.n, r.value, $('powNum').value]; type('powNum', 'abc'); out.t_abc = [L.S.n, $('powNum').value, $('powNum').getAttribute('aria-invalid')]; type('powNum', '\u22122,5'); out.t_m2c5 = [L.S.n, $('powNum').value]; type('powNum', '-0'); out.t_m0 = [L.S.n, $('powNum').value, Object.is(L.S.n, -0)]; type('powNum', '1e-7'); out.t_tiny = [L.S.n, $('powNum').value]; type('powNum', '-8'); out.t_m8 = [L.S.n, r.value]; type('powNum', '2'); return JSON.stringify(out);", "wait": "done", "timeout": 400})
# stepping: fine then whole, through 1 and 0
a.append({"js": HEAD + "const seq = []; type('powNum', '1.2'); for (let i = 0; i < 4; i++) { key('powNum', 'ArrowDown'); seq.push($('powNum').value + '=' + L.S.n); } type('powNum', '0.2'); for (let i = 0; i < 4; i++) { key('powNum', 'ArrowDown'); seq.push($('powNum').value + '=' + L.S.n); } const t0 = $('powStep').textContent; $('powStep').click(); const t1 = $('powStep').textContent; type('powNum', '2.37'); const w = []; for (let i = 0; i < 6; i++) { key('powNum', 'ArrowDown'); w.push($('powNum').value + '=' + L.S.n); } for (let i = 0; i < 3; i++) { key('powNum', 'ArrowUp'); w.push($('powNum').value + '=' + L.S.n); } type('powNum', '-7.5'); key('powNum', 'ArrowDown', { shiftKey: true }); w.push('shift-down from -7.5: ' + L.S.n); type('powNum', '-15.5'); key('powNum', 'ArrowDown'); key('powNum', 'ArrowDown'); w.push('down twice from -15.5: ' + L.S.n); $('powStep').click(); type('powNum', '2'); return JSON.stringify({ fine: seq, toggle: [t0, t1, $('powStep').textContent], whole: w });", "wait": "done", "timeout": 400})
# exact 0 and 1: what the page says
for n in ('0', '1'):
    a.append({"js": HEAD + "type('powNum', '%s'); return 'typed %s';" % (n, n), "wait": "done", "timeout": 400})
    a.append({"js": HEAD + "return JSON.stringify({ st: st(), visibleNotes: [...document.querySelectorAll('#secEq .note, #secEq .err, #stage p, #stage .msg, #stage [role=status], #stage [role=alert]')].filter(e => !e.hidden && e.offsetParent).map(e => e.textContent.slice(0, 200)), cap2d: $('cap2d').textContent, cap3d: $('cap3d').textContent, f: $('f-mercator').textContent });", "shot": "%s/dial-n%s.png" % (OUT, n)})
# dragging the slider through 1 and 0, synthetic input events, one per frame
a.append({"js": HEAD + "const r = $('pow'); let worst = 0, last = performance.now(), frames = 0; const seen = []; for (let v = 20; v >= -30; v--) { r.value = String(v / 10); r.dispatchEvent(new Event('input', { bubbles: true })); await new Promise(q => requestAnimationFrame(q)); const t = performance.now(); worst = Math.max(worst, t - last); last = t; frames++; if (v === 10 || v === 0 || v === -10 || v === -30) seen.push(L.S.n + ':' + $('status').textContent + ':' + ($('busy').hidden ? '' : $('busy').textContent)); } for (let v = -30; v <= 20; v++) { r.value = String(v / 10); r.dispatchEvent(new Event('input', { bubbles: true })); await new Promise(q => requestAnimationFrame(q)); const t = performance.now(); worst = Math.max(worst, t - last); last = t; frames++; } r.dispatchEvent(new Event('change', { bubbles: true })); return JSON.stringify({ frames, worstGapMs: Math.round(worst), seen, n: L.S.n, box: $('powNum').value });", "wait": "done", "timeout": 400})
# presets
for i, (text, tag) in enumerate((('z\u207b\u207f + c', 'preA'), ('z\u00b2 + c\u00b7z\u207b\u00b2', 'preB'))):
    for mode in ('m', 'j'):
        a.append({"js": HEAD + "$('mode-%s').click(); document.querySelector('#eqReset .dial-reset').click(); pick('eqPreset', '%s'); await new Promise(q => setTimeout(q, 200)); return JSON.stringify(st());" % (mode, text), "wait": "done", "timeout": 400, "shot": "%s/%s-%s-3d.png" % (OUT, tag, mode), "clip": "#stage"})
        a.append({"js": HEAD + "const o = { card: $('card').innerText.slice(0, 1800), st: st() }; $('flat').click(); return JSON.stringify(o);", "wait": "done", "timeout": 400, "shot": "%s/%s-%s-2d.png" % (OUT, tag, mode), "clip": "#stage"})
        a.append({"js": HEAD + "$('flat').click(); return 'flat off';"})
# preset A at other powers typed afterwards (n = 3, 4) in Mandelbrot mode
a.append({"js": HEAD + "$('mode-m').click(); document.querySelector('#eqReset .dial-reset').click(); pick('eqPreset', 'z\u207b\u207f + c'); type('powNum', '4'); return JSON.stringify(st());", "wait": "done", "timeout": 400, "shot": "%s/preA-m-n4-3d.png" % OUT, "clip": "#stage"})
json.dump(a, open(OUT + '/steps-dial.json', 'w', encoding='utf-8'), ensure_ascii=False)
